
import { useEffect, useState } from 'react'
import './App.css'
import { planScenes, buildSceneObjects } from './engine/scenePlanner'
import type { ProjectCategory, VideoFormat, VideoProject, Scene, ProjectAsset } from './engine/projectTypes'
import { createProject as storeCreateProject, getAllProjects, getProjectById, updateProject, deleteProject as storeDeleteProject } from './engine/projectStore'
import { saveProjectRevision, restoreRevision, getRevisionHistory } from './engine/revisionEngine'
import { saveProjectFiles, deleteProjectFiles, getProjectFiles } from './engine/assetStore'

type Screen = 'create' | 'projects' | 'editor'

const categories: { value: ProjectCategory; label: string }[] = [
  { value: 'auto', label: 'دع الذكاء الاصطناعي يختار' },
    { value: 'educational', label: 'تعليمي وشروحات' },
      { value: 'historical', label: 'تاريخي وسينمائي' },
        { value: 'documentary', label: 'وثائقي' },
          { value: 'storytelling', label: 'قصص وحكايات' },
            { value: 'marketing', label: 'إعلانات وتسويق' },
              { value: 'scientific', label: 'علمي ومحاكاة' },
                { value: 'social', label: 'محتوى سوشيال ميديا' },
                ]

                const formatLabels: Record<VideoFormat, string> = {
                  vertical: 'عمودي 9:16', horizontal: 'أفقي 16:9', square: 'مربع 1:1',
                  }

                  function makeScenes(idea: string, script: string, category: ProjectCategory): Scene[] {
                    return buildSceneObjects(planScenes({ idea, script, category, maxScenes: 8 }))
                    }

                    function App() {
                      const [idea, setIdea] = useState('')
                        const [script, setScript] = useState('')
                          const [projectName, setProjectName] = useState('')
                            const [category, setCategory] = useState<ProjectCategory>('auto')
                              const [format, setFormat] = useState<VideoFormat>('vertical')
                                const [voiceFile, setVoiceFile] = useState<File | null>(null)
                                  const [logoFile, setLogoFile] = useState<File | null>(null)
                                    const [referenceFiles, setReferenceFiles] = useState<File[]>([])
                                      const [projects, setProjects] = useState<VideoProject[]>([])
                                        const [activeProject, setActiveProject] = useState<VideoProject | null>(null)
                                          const [screen, setScreen] = useState<Screen>('create')
                                            const [message, setMessage] = useState('')
                                              const [revisionDescription, setRevisionDescription] = useState('')
                                                const [showHistory, setShowHistory] = useState(false)
                                                const [loadedAssets, setLoadedAssets] = useState<Array<ProjectAsset & { url: string }>>([])
                                                const [audioDuration, setAudioDuration] = useState(0)
                                                const [audioCurrentTime, setAudioCurrentTime] = useState(0)
                                                const activeAssetIds = activeProject?.assets.map((asset) => asset.id).join('|') ?? ''

                                                useEffect(() => {
                                                  let cancelled = false
                                                  let objectUrls: string[] = []
                                                  setLoadedAssets([])
                                                  if (!activeProject?.id || !activeAssetIds) return
                                                  getProjectFiles(activeProject.id).then((files) => {
                                                    if (cancelled) {
                                                      files.forEach((file) => URL.revokeObjectURL(file.url))
                                                      return
                                                    }
                                                    objectUrls = files.map((file) => file.url)
                                                    setLoadedAssets(files)
                                                  }).catch((error) => {
                                                    if (!cancelled) setMessage(error instanceof Error ? error.message : 'تعذر تحميل ملفات المشروع')
                                                  })
                                                  return () => {
                                                    cancelled = true
                                                    objectUrls.forEach((url) => URL.revokeObjectURL(url))
                                                  }
                                                }, [activeProject?.id, activeAssetIds])

                                                  function refreshProjects() {
                                                      const all = getAllProjects()
                                                          setProjects(all)
                                                              if (activeProject) {
                                                                    const fresh = all.find((p) => p.id === activeProject.id)
                                                                          if (fresh) setActiveProject(fresh)
                                                                              }
                                                                                }

                                                                                  useEffect(() => {
                                                                                      refreshProjects()
                                                                                        }, [])

                                                                                          function resetForm() {
                                                                                              setIdea(''); setScript(''); setProjectName('')
                                                                                                  setCategory('auto'); setFormat('vertical')
                                                                                                      setVoiceFile(null); setLogoFile(null); setReferenceFiles([])
                                                                                                          setMessage(''); setActiveProject(null); setScreen('create')
                                                                                                              setRevisionDescription(''); setShowHistory(false)
                                                                                                                }

                                                                                                                  async function createNewProject() {
                                                                                                                      if (!idea.trim()) { setMessage('اكتب فكرة الفيديو الأول.'); return }
                                                                                                                          try {
                                                                                                                                const project = storeCreateProject({
                                                                                                                                        name: projectName.trim() || idea.trim().slice(0, 40),
                                                                                                                                                idea: idea.trim(), script: script.trim(), category, format,
                                                                                                                                                      })
                                                                                                                                                            const scenes = makeScenes(idea.trim(), script.trim(), category)
                                                                                                                                                                  const selectedFiles = [
                                                                                                                                                                    ...(voiceFile ? [{ file: voiceFile, type: 'audio' as const }] : []),
                                                                                                                                                                    ...(logoFile ? [{ file: logoFile, type: 'logo' as const }] : []),
                                                                                                                                                                    ...referenceFiles.map((file) => ({ file, type: file.type.startsWith('video/') ? 'video' as const : 'image' as const })),
                                                                                                                                                                  ]
                                                                                                                                                                  const assets = await saveProjectFiles(project.id, selectedFiles)
                                                                                                                                                                  const updated = updateProject(project.id, { scenes, assets }) ?? project
                                                                                                                                                                        setProjects(getAllProjects())
                                                                                                                                                                              setActiveProject(updated)
                                                                                                                                                                                    setScreen('editor')
                                                                                                                                                                                          setMessage(assets.length ? `تم إنشاء المشروع وحفظ ${assets.length} ملف داخل المتصفح.` : 'تم إنشاء المشروع بنجاح.')
                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                    setMessage(error instanceof Error ? error.message : 'تعذر إنشاء المشروع أو حفظ ملفاته')
                                                                                                                                                                                                        }
                                                                                                                                                                                                          }

                                                                                                                                                                                                            function commitSceneChange(nextScenes: Scene[], description: string) {
                                                                                                                                                                                                                if (!activeProject) return
                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                          const persisted = getProjectById(activeProject.id)
                                                                                                                                                                                                                                if (!persisted) throw new Error('لم يتم العثور على المشروع المحفوظ')
                                                                                                                                                                                                                                      const updated = saveProjectRevision(persisted, nextScenes, description)
                                                                                                                                                                                                                                            if (!updated) throw new Error('لم يتم العثور على المشروع')
                                                                                                                                                                                                                                                  setActiveProject(updated)
                                                                                                                                                                                                                                                        setProjects(getAllProjects())
                                                                                                                                                                                                                                                              setMessage('تم حفظ التعديل وإنشاء نسخة سابقة قابلة للاستعادة.')
                                                                                                                                                                                                                                                                  } catch (error) {
                                                                                                                                                                                                                                                                        setMessage(error instanceof Error ? error.message : 'تعذر حفظ التعديل')
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                function updateScene(sceneId: string, field: 'title' | 'description' | 'duration', value: string | number) {
                                                                                                                                                                                                                                                                                    if (!activeProject) return
                                                                                                                                                                                                                                                                                        const next = activeProject.scenes.map((scene) => scene.id === sceneId
                                                                                                                                                                                                                                                                                              ? { ...scene, [field]: value, ...(field === 'duration' ? { endTime: scene.startTime + Number(value) } : {}) }
                                                                                                                                                                                                                                                                                                    : scene)
                                                                                                                                                                                                                                                                                                        setActiveProject({ ...activeProject, scenes: next })
                                                                                                                                                                                                                                                                                                            setMessage('التعديلات لم تُحفظ بعد. اضغط حفظ المشروع لإنشاء نسخة.')
                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                function fitScenesToAudio() {
  if (!activeProject || audioDuration <= 0 || activeProject.scenes.length === 0) {
    setMessage('حمّل ملفًا صوتيًا أولًا لقراءة مدته.');
    return;
  }
  const totalWeight = activeProject.scenes.reduce((sum, scene) => sum + Math.max(scene.duration, 0.01), 0);
  let cursor = 0;
  const nextScenes = activeProject.scenes.map((scene, index) => {
    const duration = index === activeProject.scenes.length - 1
      ? Number((audioDuration - cursor).toFixed(2))
      : Number((audioDuration * Math.max(scene.duration, 0.01) / totalWeight).toFixed(2));
    const safeDuration = Math.max(0.01, duration);
    const nextScene = { ...scene, order: index + 1, startTime: Number(cursor.toFixed(2)), duration: safeDuration, endTime: Number((cursor + safeDuration).toFixed(2)) };
    cursor += safeDuration;
    return nextScene;
  });
  commitSceneChange(nextScenes, 'توزيع مدد المشاهد على مدة الصوت');
}

function addScene() {
                                                                                                                                                                                                                                                                                                                    if (!activeProject) return
                                                                                                                                                                                                                                                                                                                        const last = activeProject.scenes[activeProject.scenes.length - 1]
                                                                                                                                                                                                                                                                                                                            const startTime = last ? last.endTime : 0
                                                                                                                                                                                                                                                                                                                                const newScene: Scene = {
                                                                                                                                                                                                                                                                                                                                      id: `scene-${Date.now()}`, order: activeProject.scenes.length,
                                                                                                                                                                                                                                                                                                                                            title: `المشهد ${activeProject.scenes.length + 1}`,
                                                                                                                                                                                                                                                                                                                                                  description: 'اكتب وصف المشهد هنا...', narration: '', duration: 5,
                                                                                                                                                                                                                                                                                                                                                        startTime, endTime: startTime + 5, assets: [], layers: [],
                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                commitSceneChange([...activeProject.scenes, newScene], 'إضافة مشهد جديد')
                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                    function deleteScene(sceneId: string) {
                                                                                                                                                                                                                                                                                                                                                                        if (!activeProject) return
                                                                                                                                                                                                                                                                                                                                                                            if (activeProject.scenes.length <= 1) { setMessage('لا يمكن حذف آخر مشهد في المشروع.'); return }
                                                                                                                                                                                                                                                                                                                                                                                commitSceneChange(activeProject.scenes.filter((scene) => scene.id !== sceneId), 'حذف مشهد')
                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                    function openProject(project: VideoProject) {
                                                                                                                                                                                                                                                                                                                                                                                        setActiveProject(project); setScreen('editor'); setMessage(''); setShowHistory(false)
                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                            function removeProject(id: string) {
                                                                                                                                                                                                                                                                                                                                                                                                if (!confirm('هل تريد حذف المشروع نهائيًا؟')) return
                                                                                                                                                                                                                                                                                                                                                                                                    storeDeleteProject(id)
                                                                                                                                                                                                                                                                    void deleteProjectFiles(id).catch((error) => console.error('تعذر حذف ملفات المشروع', error))
                                                                                                                                                                                                                                                                                                                                                                                                        setProjects(getAllProjects())
                                                                                                                                                                                                                                                                                                                                                                                                            if (activeProject?.id === id) { setActiveProject(null); setScreen('projects') }
                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                function restoreVersion(revisionId: string) {
                                                                                                                                                                                                                                                                                                                                                                                                                    if (!activeProject) return
                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                              const restored = restoreRevision(activeProject, revisionId)
                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!restored) throw new Error('تعذرت استعادة النسخة')
                                                                                                                                                                                                                                                                                                                                                                                                                                          setActiveProject(restored); setProjects(getAllProjects())
                                                                                                                                                                                                                                                                                                                                                                                                                                                setMessage('تمت استعادة النسخة، وتم تسجيل عملية الاستعادة في السجل.')
                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          setMessage(error instanceof Error ? error.message : 'تعذرت الاستعادة')
                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function saveCurrentProject() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!activeProject) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const description = revisionDescription.trim() || 'حفظ تعديلات المشروع'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const persisted = getProjectById(activeProject.id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!persisted) throw new Error('لم يتم العثور على المشروع المحفوظ')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const updated = saveProjectRevision(persisted, activeProject.scenes, description)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!updated) throw new Error('لم يتم العثور على المشروع')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setActiveProject(updated); setProjects(getAllProjects())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setRevisionDescription(''); setMessage('تم حفظ المشروع وإنشاء نقطة استعادة جديدة.')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setMessage(error instanceof Error ? error.message : 'تعذر حفظ المشروع')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const totalDuration = activeProject?.scenes.reduce((sum, scene) => sum + scene.duration, 0) ?? 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const history = activeProject ? getRevisionHistory(activeProject) : []

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <main className="app-shell" dir="rtl">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <header className="topbar">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button className="brand" onClick={resetForm}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="brand-mark">M</span><span><strong>MotionForge</strong><small>AI VIDEO STUDIO</small></span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <nav className="top-nav">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button className={screen === 'create' ? 'nav-item active' : 'nav-item'} onClick={resetForm}>مشروع جديد</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button className={screen === 'projects' ? 'nav-item active' : 'nav-item'} onClick={() => { refreshProjects(); setScreen('projects') }}>مشاريعي ({projects.length})</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </nav>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </header>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <section className="hero">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="hero-badge"><span className="status-dot" />استوديو إنتاج الفيديو</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h1>فكرتك تتحول إلى<span> فيديو متكامل</span></h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>ابدأ بفكرة فقط، واترك مساحة الإبداع لـ MotionForge. يمكنك إضافة السيناريو والصوت والملفات وقتما تريد.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {screen === 'create' && <section className="workspace">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="section-heading"><div><span className="step-label">01 — NEW PROJECT</span><h2>أنشئ مشروعك</h2><p>الفكرة هي كل ما تحتاجه للبدء.</p></div><span className="heading-icon">✦</span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="field-group"><label htmlFor="projectName">اسم المشروع <span>اختياري</span></label><input id="projectName" value={projectName} onChange={(e) => setProjectName(e.target.value)} placeholder="مثلاً: رحلة إلى أعماق المحيط" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="field-group"><label htmlFor="idea">فكرة الفيديو <span className="required">مطلوب</span></label><textarea id="idea" className="idea-input" value={idea} onChange={(e) => setIdea(e.target.value)} placeholder="اشرح فكرتك ببساطة... ما موضوع الفيديو؟" rows={5} /><div className="field-hint">اكتب الفكرة بطريقتك، حتى لو كانت مجرد سطر واحد.</div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="field-group"><label htmlFor="script">السيناريو أو السكريبت <span>اختياري</span></label><textarea id="script" value={script} onChange={(e) => setScript(e.target.value)} placeholder="الصق السيناريو هنا إن كان جاهزاً..." rows={4} /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="field-group"><label htmlFor="category">نوع المحتوى</label><select id="category" value={category} onChange={(e) => setCategory(e.target.value as ProjectCategory)}>{categories.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="field-group"><label>مقاس الفيديو</label><div className="format-grid">{(['vertical', 'horizontal', 'square'] as VideoFormat[]).map((item) => <button key={item} className={format === item ? 'format-card selected' : 'format-card'} onClick={() => setFormat(item)} type="button"><span className={`format-shape ${item}`} /><strong>{formatLabels[item]}</strong><small>{item === 'vertical' ? 'ريلز وشورتس' : item === 'horizontal' ? 'يوتيوب وشاشات' : 'منشورات مربعة'}</small></button>)}</div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="section-divider" /><div className="section-heading compact"><div><span className="step-label">02 — ASSETS</span><h2>ملفات المشروع</h2><p>ارفع ما تملكه، واترك الباقي فارغاً.</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="upload-grid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label className="upload-card"><input type="file" accept="audio/*" onChange={(e) => setVoiceFile(e.target.files?.[0] ?? null)} /><span className="upload-icon">♫</span><strong>التعليق الصوتي</strong><small>{voiceFile ? voiceFile.name : 'رفع ملف صوتي — اختياري'}</small></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label className="upload-card"><input type="file" accept="image/*" onChange={(e) => setLogoFile(e.target.files?.[0] ?? null)} /><span className="upload-icon">✧</span><strong>شعار المشروع</strong><small>{logoFile ? logoFile.name : 'رفع اللوجو — اختياري'}</small></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label className="upload-card wide"><input type="file" accept="image/*,video/*" multiple onChange={(e) => setReferenceFiles(Array.from(e.target.files ?? []))} /><span className="upload-icon">▧</span><strong>صور وفيديوهات مرجعية</strong><small>{referenceFiles.length ? `تم اختيار ${referenceFiles.length} ملف` : 'صور وفيديوهات مرجعية — اختياري'}</small></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="privacy-note"><span>ⓘ</span>تُحفظ الملفات داخل مساحة التخزين المحلية لهذا المتصفح على جهازك، ولا تُرفع إلى خادم خارجي.</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {message && <div className="error-message">{message}</div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button className="primary-button" onClick={createNewProject}><span>✦</span>إنشاء مسودة المشروع<span className="button-arrow">←</span></button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="button-note">سيتم إنشاء هيكل أولي قابل للتعديل، وليس فيديو نهائياً بعد.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </section>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {screen === 'projects' && <section className="workspace">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="section-heading"><div><span className="step-label">PROJECT LIBRARY</span><h2>مشاريعي</h2><p>المشاريع المحفوظة على هذا المتصفح.</p></div><button className="small-primary" onClick={resetForm}>+ مشروع جديد</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {projects.length === 0 ? <div className="empty-state"><span>▤</span><h3>لسه مفيش مشاريع</h3><p>ابدأ بأول فكرة فيديو عندك.</p><button className="primary-button" onClick={resetForm}>إنشاء مشروع</button></div> : <div className="project-list">{projects.map((project) => <article className="project-card" key={project.id}><div className="project-card-top"><span className="project-type">{formatLabels[project.format]}</span><button className="delete-button" onClick={() => removeProject(project.id)} aria-label="حذف المشروع">×</button></div><h3>{project.name}</h3><p>{project.idea}</p><div className="project-meta"><span>{project.scenes.length} مشاهد</span><span>الإصدار {project.version}</span></div><button className="secondary-button" onClick={() => openProject(project)}>فتح المشروع ←</button></article>)}</div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {screen === 'editor' && activeProject && <section className="workspace editor-workspace">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="editor-toolbar"><button className="back-button" onClick={() => { refreshProjects(); setScreen('projects') }}>→ رجوع</button><span className="draft-badge">مسودة محلية • v{activeProject.version}</span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="section-heading"><div><span className="step-label">PROJECT EDITOR</span><h2>{activeProject.name}</h2><p>{activeProject.idea}</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="editor-stats"><div><strong>{activeProject.scenes.length}</strong><span>مشاهد</span></div><div><strong>{totalDuration.toFixed(1)}</strong><span>ثانية مبدئية</span></div><div><strong>{formatLabels[activeProject.format]}</strong><span>المقاس</span></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="notice-box"><strong>حفظ وسجل التعديلات</strong><p>كل تعديل محفوظ ينشئ نسخة سابقة يمكنك الرجوع إليها. التوليد والرندر غير متاحين بعد في هذه النسخة.</p></div>
{activeProject.assets.length > 0 && <div className="scene-card"><strong>ملفات المشروع المحفوظة ({activeProject.assets.length})</strong><ul>{activeProject.assets.map((asset) => <li key={asset.id}>{asset.name} — {asset.type}</li>)}</ul>{loadedAssets.filter((asset) => asset.type === 'audio').map((asset) => <div key={asset.id} className="asset-audio-player"><p>{asset.name}</p><audio controls preload="metadata" src={asset.url} style={{ width: '100%' }} onLoadedMetadata={(event) => { setAudioDuration(Number.isFinite(event.currentTarget.duration) ? event.currentTarget.duration : 0); setAudioCurrentTime(0) }} onTimeUpdate={(event) => setAudioCurrentTime(event.currentTarget.currentTime)} onSeeked={(event) => setAudioCurrentTime(event.currentTarget.currentTime)} onEnded={() => setAudioCurrentTime(0)}>المتصفح لا يدعم تشغيل الصوت.</audio>{audioDuration > 0 && <small style={{ display: 'block', color: '#bda4e8', marginTop: '6px' }}>مدة الصوت الفعلية: {audioDuration.toFixed(2)} ثانية</small>}</div>)}{activeProject.scenes.length > 0 && (() => { const sceneTotal = Math.max(activeProject.totalDuration ?? 0, ...activeProject.scenes.map((item) => item.endTime), 1); const timelineTotal = audioDuration > 0 ? audioDuration : sceneTotal; const progress = timelineTotal > 0 ? Math.min(100, (audioCurrentTime / timelineTotal) * 100) : 0; return <div className="timeline-preview" style={{ marginTop: '22px', padding: '14px', border: '1px solid #393047', borderRadius: '14px' }}><strong>الخط الزمني للمشاهد</strong><p style={{ color: '#a99db8', fontSize: '12px' }}>{audioDuration > 0 ? 'تمت قراءة مدة الصوت الفعلية. مؤشر التشغيل يتحرك مع الصوت.' : 'ترتيب المشاهد ومددها الحالية — سيتم ضبط المقياس عند تحميل مدة الصوت.'}</p>{audioDuration > 0 && <button type="button" onClick={fitScenesToAudio} style={{ margin: '8px 0 12px', padding: '10px 14px', borderRadius: '10px', border: '1px solid #a879ef', background: '#38234f', color: '#f4eaff', width: '100%' }}>وزّع مدد المشاهد على الصوت ({audioDuration.toFixed(2)} ثانية)</button>}<div style={{ position: 'relative', display: 'flex', gap: '4px', width: '100%', minHeight: '58px', direction: 'ltr', overflow: 'hidden', borderRadius: '8px' }}>{activeProject.scenes.map((scene, index) => { const width = Math.max((scene.duration / sceneTotal) * 100, 4); return <div key={scene.id} title={scene.title} style={{ width: width + '%', minWidth: '28px', background: index % 2 === 0 ? '#6843a8' : '#8757c8', border: '1px solid #b58aff', borderRadius: '6px', padding: '6px 3px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', overflow: 'hidden' }}><b style={{ fontSize: '11px' }}>{index + 1}</b><small style={{ fontSize: '9px', whiteSpace: 'nowrap' }}>{scene.duration}s</small></div> })}<div aria-label="موضع تشغيل الصوت" style={{ position: 'absolute', left: progress + '%', top: 0, bottom: 0, width: '3px', background: '#fff', boxShadow: '0 0 8px #fff', pointerEvents: 'none', zIndex: 2 }} /></div><div style={{ display: 'flex', justifyContent: 'space-between', color: '#a99db8', fontSize: '11px', marginTop: '6px' }}><span>{Math.floor(audioCurrentTime / 60).toString().padStart(2, '0')}:{Math.floor(audioCurrentTime % 60).toString().padStart(2, '0')}</span><span>{timelineTotal.toFixed(2)} ثانية</span></div></div> })()}</div>}
<div className="scene-list">{activeProject.scenes.map((scene, index) => <article className="scene-card" key={scene.id}><div className="scene-card-heading"><span className="scene-number">{String(index + 1).padStart(2, '0')}</span><input className="scene-title-input" value={scene.title} onChange={(e) => updateScene(scene.id, 'title', e.target.value)} /><button className="delete-button" onClick={() => deleteScene(scene.id)} aria-label="حذف المشهد">×</button></div><label>وصف المشهد</label><textarea value={scene.description} rows={3} onChange={(e) => updateScene(scene.id, 'description', e.target.value)} /><div className="duration-control"><label>المدة التقديرية بالثواني</label><input type="number" min={1} max={120} value={scene.duration} onChange={(e) => updateScene(scene.id, 'duration', Math.max(1, Number(e.target.value)))} /></div></article>)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button className="secondary-button add-scene" onClick={addScene}>+ إضافة مشهد</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="field-group"><label htmlFor="revisionDescription">وصف نقطة الحفظ <span>اختياري</span></label><input id="revisionDescription" value={revisionDescription} onChange={(e) => setRevisionDescription(e.target.value)} placeholder="مثلاً: تعديل المشهد الافتتاحي" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button className="primary-button" onClick={saveCurrentProject}>حفظ المشروع وإنشاء نسخة</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button className="secondary-button add-scene" onClick={() => setShowHistory((value) => !value)}>{showHistory ? 'إخفاء سجل التعديلات' : `عرض سجل التعديلات (${history.length})`}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {showHistory && <div className="scene-list">{history.length === 0 ? <p>لا توجد نسخ محفوظة حتى الآن.</p> : history.map((revision) => <article className="scene-card" key={revision.id}><strong>{revision.description}</strong><p>{new Date(revision.createdAt).toLocaleString('ar-EG')}</p><small>المشاهد المتأثرة: {revision.affectedSceneIds.length}</small><button className="secondary-button" onClick={() => restoreVersion(revision.id)}>استعادة الحالة السابقة</button></article>)}</div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {message && <div className="success-message">{message}</div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </section>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <footer className="footer"><div className="footer-brand">MotionForge <span>STUDIO</span></div><p>من الفكرة إلى الإنتاج — خطوة بخطوة.</p><small>Prototype • Local project drafts</small></footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        export default App
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        